"""Regenerate requirements.txt and environment.yml from pyproject.toml.

    python tools/sync_requirements.py
"""
from __future__ import annotations

from pathlib import Path

try:
    import tomllib
except ModuleNotFoundError:  # Python 3.10
    import tomli as tomllib

ROOT = Path(__file__).resolve().parents[1]


def main() -> None:
    proj = tomllib.loads((ROOT / "pyproject.toml").read_text(encoding="utf8"))["project"]
    deps = proj["dependencies"]
    (ROOT / "requirements.txt").write_text(
        "# generated by tools/sync_requirements.py from pyproject.toml\n" + "\n".join(deps) + "\n",
        encoding="utf8", newline="\n")
    pip_lines = "\n".join(f"      - \"{d}\"" for d in deps)
    (ROOT / "environment.yml").write_text(
        "# generated by tools/sync_requirements.py from pyproject.toml\n"
        "name: microplastic-detection-ml\nchannels:\n  - conda-forge\ndependencies:\n"
        f"  - python>={proj['requires-python'].lstrip('>=')},<3.14\n  - pip\n  - pip:\n{pip_lines}\n"
        "      - -e .\n", encoding="utf8", newline="\n")
    print("requirements.txt and environment.yml written")


if __name__ == "__main__":
    main()
